               var x0 = Math.floor( xi ), y0 = Math.floor( yi );
               var x1 = x0 < w - 1 ? x0 + 1 : x0, y1 = y0 < h - 1 ? y0 + 1 : y0;
               var fx = xi - x0, fy = yi - y0;
               var p = img[y0 * w + x0], q2 = img[y0 * w + x1], r = img[y1 * w + x0], t = img[y1 * w + x1];
